#![no_main]
#![allow(static_mut_refs)]
sp1_zkvm::entrypoint!(main);

use prova_common::{Account, Address, Input, Log, Public, State, Word};
use sp1_zkvm::io::{commit, read};
use std::collections::BTreeMap;
use tiny_keccak::{Hasher, Keccak};

/// A contract linked into this program: its name and its two entry points.
struct Code {
    name: &'static str,
    deploy: unsafe extern "C" fn(*const u8, u32),
    call: unsafe extern "C" fn(*const u8, u32),
}

// `CODES` and the entry points' declarations, generated by build.rs.
include!(concat!(env!("OUT_DIR"), "/contracts.rs"));

/// As on Ethereum: a call deeper than this fails.
const MAX_DEPTH: usize = 1024;

// Entering and leaving a call frame. An entry point never returns: it ends in
// `__sys_return` or `__sys_revert`, deep inside the contract's own calls.
// `prova_enter` saves the callee-saved registers, `sp` and `ra` in a
// `Resume`, then calls the entry point; `prova_leave` restores them, so that
// `prova_enter` returns (again) with the status. What ran in between, the
// contract's frames and the guest's `__sys_*` frame, is dropped without
// unwinding: those frames own nothing that needs dropping.
core::arch::global_asm!(
    ".globl prova_enter",
    "prova_enter:", // a0 = entry, a1 = input, a2 = len, a3 = resume
    "sd ra, 0(a3)",
    "sd sp, 8(a3)",
    "sd s0, 16(a3)",
    "sd s1, 24(a3)",
    "sd s2, 32(a3)",
    "sd s3, 40(a3)",
    "sd s4, 48(a3)",
    "sd s5, 56(a3)",
    "sd s6, 64(a3)",
    "sd s7, 72(a3)",
    "sd s8, 80(a3)",
    "sd s9, 88(a3)",
    "sd s10, 96(a3)",
    "sd s11, 104(a3)",
    "mv t0, a0",
    "mv a0, a1",
    "mv a1, a2",
    "jalr t0",
    "call prova_entry_returned",
    ".globl prova_leave",
    "prova_leave:", // a0 = resume, a1 = status
    "ld ra, 0(a0)",
    "ld sp, 8(a0)",
    "ld s0, 16(a0)",
    "ld s1, 24(a0)",
    "ld s2, 32(a0)",
    "ld s3, 40(a0)",
    "ld s4, 48(a0)",
    "ld s5, 56(a0)",
    "ld s6, 64(a0)",
    "ld s7, 72(a0)",
    "ld s8, 80(a0)",
    "ld s9, 88(a0)",
    "ld s10, 96(a0)",
    "ld s11, 104(a0)",
    "mv a0, a1",
    "ret",
);

/// The registers `prova_enter` saves: ra, sp, s0-s11.
#[repr(C)]
#[derive(Default)]
struct Resume([u64; 14]);

extern "C" {
    fn prova_enter(
        entry: unsafe extern "C" fn(*const u8, u32),
        input: *const u8,
        len: u32,
        resume: *mut Resume,
    ) -> u64;
    fn prova_leave(resume: *const Resume, status: u64) -> !;
}

#[no_mangle]
extern "C" fn prova_entry_returned() -> ! {
    panic!("a contract entry point returned instead of calling __sys_return or __sys_revert");
}

/// One call: whose storage and context it runs in, and where to resume.
struct Frame {
    /// `address(this)`: the storage and events of this frame.
    address: Address,
    caller: Address,
    value: Word,
    /// No storage writes or events (a `staticcall`, or below one).
    is_static: bool,
    /// The journal and log lengths when the frame started; a revert goes back
    /// to them.
    journal_len: usize,
    logs_len: usize,
    resume: Resume,
}

/// The world the transaction runs in.
struct World {
    input: Input,
    /// Which linked contract runs at each address (an index into `CODES`).
    code: BTreeMap<Address, usize>,
    storage: BTreeMap<(Address, Word), Word>,
    /// Every storage write, with the value it replaced (None: no value).
    journal: Vec<(Address, Word, Option<Word>)>,
    logs: Vec<Log>,
    /// The call stack; boxed, so a frame's `resume` stays put.
    frames: Vec<Box<Frame>>,
    /// What the innermost frame that ended returned or reverted with.
    output: Vec<u8>,
    /// The output of the last call this frame made (`returndata`).
    returndata: Vec<u8>,
}

static mut WORLD: Option<World> = None;

fn world() -> &'static mut World {
    unsafe { WORLD.as_mut().unwrap() }
}

fn frame() -> &'static Frame {
    world().frames.last().unwrap()
}

fn code_index(name: &str) -> usize {
    CODES
        .iter()
        .position(|code| code.name == name)
        .unwrap_or_else(|| panic!("no contract named {name} is linked into this program"))
}

pub fn main() {
    let input: Input = read();

    let mut code = BTreeMap::new();
    let mut storage = BTreeMap::new();
    for account in &input.state {
        code.insert(account.address, code_index(&account.code));
        for (slot, value) in &account.storage {
            storage.insert((account.address, *slot), *value);
        }
    }

    let context = input.context.clone();
    let entry = match &input.deploy {
        // As on Ethereum, deploying over an existing contract fails.
        Some(_) if code.contains_key(&context.address) => None,
        Some(name) => {
            let index = code_index(name);
            code.insert(context.address, index);
            Some(CODES[index].deploy)
        }
        None => code.get(&context.address).map(|index| CODES[*index].call),
    };

    let calldata = input.calldata.clone();
    let deploy = input.deploy.is_some();
    unsafe {
        WORLD = Some(World {
            input,
            code,
            storage,
            journal: Vec::new(),
            logs: Vec::new(),
            frames: Vec::new(),
            output: Vec::new(),
            returndata: Vec::new(),
        });
    }

    let (reverted, output) = match entry {
        Some(entry) => run(
            entry,
            &calldata,
            context.address,
            context.caller,
            context.value,
            false,
        ),
        None => (deploy, Vec::new()),
    };
    finish(reverted, output);
}

/// Runs an entry point in a new frame: (reverted, output). A revert undoes
/// the frame's storage writes and events.
fn run(
    entry: unsafe extern "C" fn(*const u8, u32),
    input: &[u8],
    address: Address,
    caller: Address,
    value: Word,
    is_static: bool,
) -> (bool, Vec<u8>) {
    let world = world();
    if world.frames.len() >= MAX_DEPTH {
        return (true, Vec::new());
    }
    world.frames.push(Box::new(Frame {
        address,
        caller,
        value,
        is_static,
        journal_len: world.journal.len(),
        logs_len: world.logs.len(),
        resume: Resume::default(),
    }));
    let resume: *mut Resume = &mut world.frames.last_mut().unwrap().resume;

    let status = unsafe { prova_enter(entry, input.as_ptr(), input.len() as u32, resume) };

    let world = self::world();
    let frame = world.frames.pop().unwrap();
    let reverted = status != 0;
    if reverted {
        while world.journal.len() > frame.journal_len {
            let (address, slot, old) = world.journal.pop().unwrap();
            match old {
                Some(value) => world.storage.insert((address, slot), value),
                None => world.storage.remove(&(address, slot)),
            };
        }
        world.logs.truncate(frame.logs_len);
    }
    (reverted, core::mem::take(&mut world.output))
}

/// Ends the innermost frame: back to where `run` entered it.
fn leave(reverted: bool, data: *const u8, len: u64) -> ! {
    let world = world();
    world.output = bytes(data, len).to_vec();
    println!(
        "  {}{} 0x{}",
        indent(),
        if reverted { "revert" } else { "return" },
        bytes_hex(&world.output)
    );
    let resume: *const Resume = &world.frames.last().unwrap().resume;
    unsafe { prova_leave(resume, reverted as u64) }
}

/// Trace lines of nested frames are indented.
fn indent() -> String {
    "  ".repeat(world().frames.len().saturating_sub(1))
}

// Solang passes 256-bit values as four u64 limbs, least significant first.
fn to_word(limbs: [u64; 4]) -> Word {
    let mut word = [0; 32];
    for (i, limb) in limbs.iter().enumerate() {
        word[24 - 8 * i..32 - 8 * i].copy_from_slice(&limb.to_be_bytes());
    }
    word
}

fn to_limbs(word: &Word) -> [u64; 4] {
    core::array::from_fn(|i| u64::from_be_bytes(word[24 - 8 * i..32 - 8 * i].try_into().unwrap()))
}

#[no_mangle]
extern "C" fn __sys_sload(k0: u64, k1: u64, k2: u64, k3: u64, out: *mut [u64; 4]) {
    let key = to_word([k0, k1, k2, k3]);
    let value = world()
        .storage
        .get(&(frame().address, key))
        .copied()
        .unwrap_or_default();
    println!("  {}sload  {} -> {}", indent(), hex(&key), hex(&value));
    unsafe { *out = to_limbs(&value) };
}

#[no_mangle]
#[allow(clippy::too_many_arguments)]
extern "C" fn __sys_sstore(k0: u64, k1: u64, k2: u64, k3: u64, v0: u64, v1: u64, v2: u64, v3: u64) {
    if frame().is_static {
        println!("  {}sstore in a static call", indent());
        leave(true, core::ptr::null(), 0);
    }
    let key = to_word([k0, k1, k2, k3]);
    let value = to_word([v0, v1, v2, v3]);
    println!("  {}sstore {} <- {}", indent(), hex(&key), hex(&value));
    let world = world();
    let address = frame().address;
    let old = world.storage.insert((address, key), value);
    world.journal.push((address, key, old));
}

#[no_mangle]
extern "C" fn __sys_keccak256(data: *const u8, len: u64, out: *mut [u8; 32]) {
    let data = bytes(data, len);
    let mut keccak = Keccak::v256();
    keccak.update(data);
    unsafe { keccak.finalize(&mut *out) };
    println!(
        "  {}keccak 0x{} -> 0x{}",
        indent(),
        bytes_hex(data),
        bytes_hex(unsafe { &*out })
    );
}

/// `topics` is `n_topics` 32-byte words, next to each other.
#[no_mangle]
extern "C" fn __sys_log(data: *const u8, len: u64, topics: *const u8, n_topics: u64) {
    if frame().is_static {
        println!("  {}log in a static call", indent());
        leave(true, core::ptr::null(), 0);
    }
    assert!(n_topics <= 4, "an event has at most 4 topics");
    let topics: Vec<Word> = bytes(topics, 32 * n_topics)
        .chunks(32)
        .map(|topic| topic.try_into().unwrap())
        .collect();
    let data = bytes(data, len).to_vec();
    println!(
        "  {}log    [{}] 0x{}",
        indent(),
        topics.iter().map(hex).collect::<Vec<_>>().join(", "),
        bytes_hex(&data)
    );
    world().logs.push(Log {
        address: frame().address,
        topics,
        data,
    });
}

#[no_mangle]
extern "C" fn __sys_caller(out: *mut Address) {
    unsafe { *out = frame().caller };
}

#[no_mangle]
extern "C" fn __sys_callvalue(out: *mut [u64; 4]) {
    unsafe { *out = to_limbs(&frame().value) };
}

#[no_mangle]
extern "C" fn __sys_address(out: *mut Address) {
    unsafe { *out = frame().address };
}

#[no_mangle]
extern "C" fn __sys_block_number() -> u64 {
    world().input.context.block_number
}

#[no_mangle]
extern "C" fn __sys_timestamp() -> u64 {
    world().input.context.timestamp
}

/// Calls the contract at `address`: 0 if it returned, 1 if it reverted. The
/// value is passed on as the callee's `msg.value`; no balance moves.
#[no_mangle]
extern "C" fn __sys_call(
    address: *const Address,
    value: *const [u64; 4],
    input: *const u8,
    len: u64,
) -> u64 {
    let (address, value) = unsafe { (*address, to_word(*value)) };
    let current = frame();
    if current.is_static && value != [0; 32] {
        world().returndata.clear();
        return 1;
    }
    call(
        "call",
        address,
        address,
        current.address,
        value,
        current.is_static,
        input,
        len,
    )
}

/// Calls the contract at `address` without letting it, or anything it calls,
/// write storage or emit events.
#[no_mangle]
extern "C" fn __sys_staticcall(address: *const Address, input: *const u8, len: u64) -> u64 {
    let address = unsafe { *address };
    call(
        "staticcall",
        address,
        address,
        frame().address,
        [0; 32],
        true,
        input,
        len,
    )
}

/// Runs the code at `address` in this frame's storage and context.
#[no_mangle]
extern "C" fn __sys_delegatecall(address: *const Address, input: *const u8, len: u64) -> u64 {
    let current = frame();
    let code = unsafe { *address };
    call(
        "delegatecall",
        code,
        current.address,
        current.caller,
        current.value,
        current.is_static,
        input,
        len,
    )
}

/// Runs the code at `code` in a new frame for `address`, and keeps its
/// output as the return data.
#[allow(clippy::too_many_arguments)]
fn call(
    kind: &str,
    code: Address,
    address: Address,
    caller: Address,
    value: Word,
    is_static: bool,
    input: *const u8,
    len: u64,
) -> u64 {
    // The callee's input is copied out of the caller's memory.
    let input = bytes(input, len).to_vec();
    println!(
        "  {}{kind} {} 0x{}",
        indent(),
        short_address(&code),
        bytes_hex(&input)
    );
    let Some(index) = world().code.get(&code).copied() else {
        // As on Ethereum, calling an address without code succeeds.
        world().returndata.clear();
        return 0;
    };
    let (reverted, output) = run(CODES[index].call, &input, address, caller, value, is_static);
    world().returndata = output;
    reverted as u64
}

#[no_mangle]
extern "C" fn __sys_returndata_size() -> u64 {
    world().returndata.len() as u64
}

/// Copies `returndata[offset..offset + len]` to `dest`; out of range reverts.
#[no_mangle]
extern "C" fn __sys_returndata_copy(dest: *mut u8, offset: u64, len: u64) {
    let data = &world().returndata;
    let Some(source) = offset
        .checked_add(len)
        .and_then(|end| data.get(offset as usize..end as usize))
    else {
        leave(true, core::ptr::null(), 0);
    };
    if len > 0 {
        unsafe { core::ptr::copy_nonoverlapping(source.as_ptr(), dest, len as usize) };
    }
}

#[no_mangle]
extern "C" fn __sys_return(data: *const u8, len: u64) -> ! {
    leave(false, data, len)
}

#[no_mangle]
extern "C" fn __sys_revert(data: *const u8, len: u64) -> ! {
    leave(true, data, len)
}

/// The contract's bytes; `data` may be null when `len` is 0.
fn bytes<'a>(data: *const u8, len: u64) -> &'a [u8] {
    if len == 0 {
        &[]
    } else {
        unsafe { core::slice::from_raw_parts(data, len as usize) }
    }
}

/// The state as the host sees it: one account per contract, sorted.
fn state(world: &World) -> State {
    world
        .code
        .iter()
        .map(|(address, index)| Account {
            address: *address,
            code: CODES[*index].name.to_string(),
            storage: world
                .storage
                .range((*address, [0; 32])..=(*address, [0xff; 32]))
                .map(|((_, slot), value)| (*slot, *value))
                .collect(),
        })
        .collect()
}

/// Commits the public values. A top-level revert keeps the state as it was:
/// no storage writes, no new contract, no events.
fn finish(reverted: bool, output: Vec<u8>) -> ! {
    let world = unsafe { WORLD.take().unwrap() };
    let (state_after, logs) = if reverted {
        (world.input.state.clone(), Vec::new())
    } else {
        (state(&world), world.logs)
    };
    let input = world.input;
    commit(&Public {
        context: input.context,
        deploy: input.deploy,
        calldata: input.calldata,
        state_before: input.state,
        reverted,
        output,
        logs,
        state_after,
    });

    sp1_zkvm::syscalls::syscall_halt(0)
}

fn short_address(address: &Address) -> String {
    let mut word = [0; 32];
    word[12..].copy_from_slice(address);
    hex(&word)
}

fn hex(word: &Word) -> String {
    let digits = bytes_hex(word);
    let digits = digits.trim_start_matches('0');
    format!("0x{}", if digits.is_empty() { "0" } else { digits })
}

fn bytes_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}
